/* ============ status-fx.js — on-sprite status animations (#78) ============
 * Every Pokemon on the field (yours, gym leaders, wild enemies) shows its statuses and stat changes as small looping
 * animations on its sprite. Spec: docs/HUD-STYLE.md "On-sprite status icons (#71)". Art and frame data: assets/status/
 * and G.STATUS_ANIMS (js/data/status-anims.js, generated by tools/status_anims.js).
 *
 *   drawBehind(ctx, pokemon, lift)  before the sprite: the stat-up ring, which plays once each time a stage is gained
 *   drawFront(ctx, pokemon, lift)   after the sprite: everything else, by spot, majors on top of minors
 *
 * Spots are the game's own points: the feet (the entity's x, y), the head (y - bodyH) and the body centre, halfway
 * between. Effects scale with the Pokemon. Each Pokemon starts its loops at its own random point so a swarm does not
 * pulse in step. Sleep has no art: its three Z's are drawn here.
 */
G.StatusFx = (() => {
  const ANIMS = G.STATUS_ANIMS;
  const STAT_SPREAD_ART = 3; // several stat changes sit this many art pixels from the body centre, evenly round a circle
  const STAT_TIME_STEP = 1 / 3; // and each starts this much of its loop after the one before
  const ABOVE_HEAD_MINORS = ['drowsy', 'daze', 'confusion']; // bottom to top (Jess, 2026-11-11)
  const SLEEP = {
    cycleMs: 1800,
    fill: '#d83860',
    outline: '#101010',
    letters: [
      { sizeArt: 5, phaseOffset: 0 },
      { sizeArt: 7, phaseOffset: 1 / 3 },
      { sizeArt: 9, phaseOffset: 2 / 3 },
    ],
  };

  // ---------- sheets and timing ----------
  const images = new Map(); // path -> { img, ready }
  function sheetImage(path) {
    let entry = images.get(path);
    if (!entry) {
      const img = new Image();
      entry = { img, ready: false };
      img.onload = () => (entry.ready = true);
      img.src = path;
      images.set(path, entry);
    }
    return entry.ready ? entry.img : null;
  }
  // Each animation's loop length and the time each frame ends, for picking the frame at a moment.
  const timing = {};
  for (const key in ANIMS) {
    let total = 0;
    timing[key] = { frameEnds: ANIMS[key].frameMs.map((ms) => (total += ms)), loopMs: 0 };
    timing[key].loopMs = total;
  }
  function frameAt(key, timeMs) {
    const { frameEnds, loopMs } = timing[key],
      within = ((timeMs % loopMs) + loopMs) % loopMs;
    for (let index = 0; index < frameEnds.length; index++) if (within < frameEnds[index]) return index;
    return frameEnds.length - 1;
  }

  /** Draws one frame of an animation with its pivot on (x, y), scaled by `scale` world units per art pixel. */
  function drawFrame(ctx, key, image, frame, x, y, scale) {
    const anim = ANIMS[key];
    if (!image) return;
    ctx.drawImage(
      image,
      frame * anim.frameWidth,
      0,
      anim.frameWidth,
      anim.frameHeight,
      Math.round(x - anim.pivot[0] * scale),
      Math.round(y - anim.pivot[1] * scale),
      anim.frameWidth * scale,
      anim.frameHeight * scale
    );
  }

  // ---------- per-Pokemon memory: its random loop start and its last stat stages (for the ring) ----------
  const memory = new WeakMap();
  function memoryOf(pokemon) {
    let entry = memory.get(pokemon);
    if (!entry) {
      entry = { phaseMs: Math.random() * 60000, stages: null, ringStartMs: -Infinity };
      memory.set(pokemon, entry);
    }
    return entry;
  }

  function pointsOf(pokemon, lift) {
    const feetY = pokemon.y - (lift || 0),
      bodyHeight = pokemon.bodyH || 0;
    return {
      x: pokemon.x,
      feet: feetY,
      body: feetY - bodyHeight / 2,
      head: feetY - bodyHeight,
      scale: G.Sprites.PX * (pokemon.anim && pokemon.anim.scale ? pokemon.anim.scale : 1),
    };
  }

  /** The status keys on a Pokemon, read straight from its fields (G.Status.list allocates, and this runs for every enemy). */
  function majorOf(pokemon) {
    if (pokemon.stMajor) return pokemon.stMajor.k;
    if (pokemon.stDot) return pokemon.stDot.k;
    if (pokemon.burn > 0) return 'burn';
    if (pokemon.poison > 0) return pokemon.poison === 2 ? 'toxic' : 'poison';
    return null;
  }
  function minorsOf(pokemon) {
    return {
      confusion: !!pokemon.stCnf,
      daze: !!pokemon.stDaze,
      drowsy: !!pokemon.stDrow,
      trap: !!pokemon.stTrap,
    };
  }

  /** Raised and lowered stats, in G.Stages.STATS order. */
  function statChangesOf(pokemon) {
    const raised = [],
      lowered = [];
    for (const stat of G.Stages.STATS) {
      const stage = G.Stages.stage(pokemon, stat);
      if (stage > 0) raised.push(stat);
      else if (stage < 0) lowered.push(stat);
    }
    return { raised, lowered };
  }

  // ---------- behind the sprite: the stat-up ring ----------
  function drawBehind(ctx, pokemon, lift) {
    if (pokemon.dead) return;
    const remembered = memoryOf(pokemon),
      nowMs = performance.now();
    // A stage gained since the last frame starts the ring. The first look only records, so a Pokemon scrolling into view
    // with a raise it already had does not ring.
    const stages = remembered.stages;
    let gained = false;
    for (const stat of G.Stages.STATS) {
      const stage = G.Stages.stage(pokemon, stat);
      if (stages && stage > (stages[stat] || 0)) gained = true;
      (remembered.stages || (remembered.stages = {}))[stat] = stage;
    }
    if (gained) remembered.ringStartMs = nowMs;
    const sinceRingMs = nowMs - remembered.ringStartMs;
    if (sinceRingMs >= timing['stat-up-ring'].loopMs) return;
    const points = pointsOf(pokemon, lift);
    drawFrame(
      ctx,
      'stat-up-ring',
      sheetImage(ANIMS['stat-up-ring'].image),
      frameAt('stat-up-ring', sinceRingMs),
      points.x,
      points.feet,
      points.scale
    );
  }

  // ---------- in front of the sprite ----------
  /** Offsets (art pixels) for `count` effects evenly round a circle; two sit diagonally, one stays centred. */
  function spreadOffsets(count) {
    if (count <= 1) return [[0, 0]];
    const start = count === 2 ? (-3 * Math.PI) / 4 : -Math.PI / 2;
    return Array.from({ length: count }, (_, index) => {
      const angle = start + (2 * Math.PI * index) / count;
      return [STAT_SPREAD_ART * Math.cos(angle), STAT_SPREAD_ART * Math.sin(angle)];
    });
  }

  function drawStatChanges(ctx, pokemon, points, timeMs) {
    const { raised, lowered } = statChangesOf(pokemon),
      effects = raised.map((stat) => ['stat-up', stat]).concat(lowered.map((stat) => ['stat-down', stat]));
    if (!effects.length) return;
    const offsets = spreadOffsets(effects.length);
    effects.forEach(([key, stat], index) => {
      const startMs = index * STAT_TIME_STEP * timing[key].loopMs;
      drawFrame(
        ctx,
        key,
        sheetImage(ANIMS[key].statImages[stat]),
        frameAt(key, timeMs - startMs),
        points.x + offsets[index][0] * points.scale,
        points.body + offsets[index][1] * points.scale,
        points.scale
      );
    });
  }

  function drawLoop(ctx, key, points, spot, timeMs) {
    drawFrame(ctx, key, sheetImage(ANIMS[key].image), frameAt(key, timeMs), points.x, points[spot], points.scale);
  }

  /** Sleep: three Z's of growing size rising up and to the right one after another, fading in and out. */
  function drawSleep(ctx, points, timeMs) {
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';
    ctx.lineJoin = 'round';
    ctx.fillStyle = SLEEP.fill;
    ctx.strokeStyle = SLEEP.outline;
    ctx.lineWidth = points.scale;
    for (const letter of SLEEP.letters) {
      const phase = (timeMs / SLEEP.cycleMs + letter.phaseOffset) % 1,
        x = points.x + (-2 + 12 * phase) * points.scale,
        y = points.head - (2 + 22 * phase) * points.scale;
      ctx.globalAlpha = Math.sin(phase * Math.PI);
      ctx.font = '800 ' + Math.round(letter.sizeArt * points.scale) + 'px GameFont,"Segoe UI",sans-serif';
      ctx.strokeText('Z', x, y);
      ctx.fillText('Z', x, y);
    }
    ctx.restore();
  }

  function drawFront(ctx, pokemon, lift) {
    if (pokemon.dead) return;
    const points = pointsOf(pokemon, lift),
      timeMs = performance.now() + memoryOf(pokemon).phaseMs,
      major = majorOf(pokemon),
      minors = minorsOf(pokemon);
    // The feet: burn and the poisons are all majors, so nothing sits under them there.
    if (major === 'burn' || major === 'poison' || major === 'toxic') drawLoop(ctx, major, points, 'feet', timeMs);
    // The body: the minors (stat changes, trap), then the major on top.
    drawStatChanges(ctx, pokemon, points, timeMs);
    if (minors.trap) drawLoop(ctx, 'trap', points, 'body', timeMs);
    if (major === 'freeze' || major === 'paralysis') drawLoop(ctx, major, points, 'body', timeMs);
    // Above the head: the minors bottom to top, then sleep on top.
    for (const key of ABOVE_HEAD_MINORS) if (minors[key]) drawLoop(ctx, key, points, 'head', timeMs);
    if (major === 'sleep') drawSleep(ctx, points, timeMs);
  }

  /** Loads every sheet up front, so the first status a Pokemon gets does not blink in a frame late. */
  function preload() {
    for (const key in ANIMS) {
      sheetImage(ANIMS[key].image);
      if (ANIMS[key].statImages) for (const stat in ANIMS[key].statImages) sheetImage(ANIMS[key].statImages[stat]);
    }
  }
  preload();

  return { drawBehind, drawFront, spreadOffsets, frameAt };
})();
